query:
subscription SystemMonitoring($metrics: [MetricType!]) {
  systemMetrics(metrics: $metrics) {
    timestamp
    server {
      cpu {
        usage
        loadAverage
        cores
      }
      memory {
        used
        total
        percentage
        available
      }
      disk {
        used
        total
        percentage
      }
    }
    database {
      connections {
        active
        idle
        total
      }
      performance {
        queriesPerSecond
        avgQueryTime
        slowQueries
      }
      storage {
        size
        tables
        indexes
      }
    }
    alerts {
      level
      message
      timestamp
      component
    }
  }
}
